.cards { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; }
.cards > article { min-width:0; overflow-wrap:anywhere; }
.cards pre { max-width:100%; overflow:auto; }
@media (max-width:36rem) { .cards { grid-template-columns:1fr; } }

/* 配套结构：main.page 内放一个 section.cards，包含多个 article */
* { box-sizing:border-box; }
body { margin:0; }
.page {
  width:min(100%,68rem);
  margin-inline:auto;
  padding:1rem;
  min-height:100vh;
  min-height:100dvh;
}
.cards { display:grid; grid-template-columns:1fr; gap:1rem; }
img { max-width:100%; height:auto; }
@media (min-width:48rem) {
  .cards { grid-template-columns:repeat(2,minmax(0,1fr)); }
}

.stack { display:flow-root; }
.stack > div { height:20px; background:#cde; }
.stack > div:first-child { margin-bottom:20px; }
.stack > div + div { margin-top:12px; }
